SELECT SUM(units_sold) AS total_units, SUM(revenue_inr) AS total_revenue, COUNT(*) AS days
FROM store.daily_sales
WHERE sku = 'ATTA-WW-5KG' AND date >= '2026-06-01' AND date <= '2026-06-30';

SELECT SUM(qty) AS pos_units, SUM(line_amount) AS pos_amount, COUNT(DISTINCT bill_id) AS bills
FROM store.pos_lines
WHERE sku_scanned = 'ATTA-WW-5KG' AND bill_ts >= '2026-06-01' AND bill_ts < '2026-07-01';

SELECT COUNT(DISTINCT bill_id) AS bills_with_atta, COUNT(*) AS lines
